pub fn bmat(
    top_left: Vec<f32>,
    top_right: Vec<f32>,
    bottom_left: Vec<f32>,
    bottom_right: Vec<f32>,
) -> Vec<f32> {
    let n = top_left.len();
    assert_eq!(top_right.len(), n, "top_right length must match top_left");
    assert_eq!(bottom_left.len(), n, "bottom_left length must match top_left");
    assert_eq!(bottom_right.len(), n, "bottom_right length must match top_left");

    let total = n.checked_mul(4).expect("output length overflow");
    let mut result = Vec::with_capacity(total);

    // Move elements in the required order.
    result.extend(top_left);
    result.extend(top_right);
    result.extend(bottom_left);
    result.extend(bottom_right);

    debug_assert_eq!(result.len(), total);
    result
}